-- Self-checking testbench for ECE 520/L Lab 3.
-- Clock period is 20 ns (50 MHz). The testbench reads expected test words
-- from sim/input_data.txt, generated by scripts/generate_fifo_data.py.

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use ieee.std_logic_textio.all;
use std.textio.all;
use std.env.all;

entity tb_sc_fifo is
    generic (
        G_READ_LATENCY : positive := 1;
        G_INPUT_FILE   : string   := "sim/input_data.txt"
    );
end entity tb_sc_fifo;

architecture simulation of tb_sc_fifo is
    constant WIDTH                  : positive := 16;
    constant DEPTH                  : positive := 32;
    constant ALMOST_EMPTY_THRESHOLD : natural  := 1;
    constant ALMOST_FULL_THRESHOLD  : natural  := 31;
    constant COUNT_WIDTH            : positive := 6;
    constant CLK_PERIOD             : time     := 20 ns;

    type word_array_t is array (0 to DEPTH - 1) of
        std_logic_vector(WIDTH - 1 downto 0);

    signal clk          : std_logic := '0';
    signal srst         : std_logic := '0';
    signal din          : std_logic_vector(WIDTH - 1 downto 0) := (others => '0');
    signal wr_en        : std_logic := '0';
    signal rd_en        : std_logic := '0';
    signal dout         : std_logic_vector(WIDTH - 1 downto 0);
    signal full         : std_logic;
    signal empty        : std_logic;
    signal almost_full  : std_logic;
    signal almost_empty : std_logic;
    signal valid        : std_logic;
    signal data_count   : std_logic_vector(COUNT_WIDTH - 1 downto 0);
begin
    dut : entity work.sc_fifo
        generic map (
            WIDTH                  => WIDTH,
            DEPTH                  => DEPTH,
            ALMOST_EMPTY_THRESHOLD => ALMOST_EMPTY_THRESHOLD,
            ALMOST_FULL_THRESHOLD  => ALMOST_FULL_THRESHOLD,
            READ_LATENCY           => G_READ_LATENCY
        )
        port map (
            CLK          => clk,
            SRST         => srst,
            DIN          => din,
            WR_EN        => wr_en,
            RD_EN        => rd_en,
            DOUT         => dout,
            FULL         => full,
            EMPTY        => empty,
            ALMOST_FULL  => almost_full,
            ALMOST_EMPTY => almost_empty,
            VALID        => valid,
            DATA_COUNT   => data_count
        );

    clock_process : process
    begin
        clk <= '0';
        wait for CLK_PERIOD / 2;
        clk <= '1';
        wait for CLK_PERIOD / 2;
    end process;

    stimulus : process
        file input_file : text;
        variable file_status : file_open_status;
        variable input_line  : line;
        variable parsed_word : std_logic_vector(WIDTH - 1 downto 0);
        variable file_words  : word_array_t;

        -- Wait for a rising clock edge, then allow signal updates to settle.
        procedure cycle is
        begin
            wait until rising_edge(clk);
            wait for 1 ns;
        end procedure;

        -- Check the count and all four FIFO status flags.
        procedure check_state(
            constant expected_count : in natural;
            constant test_name      : in string
        ) is
        begin
            assert to_integer(unsigned(data_count)) = expected_count
                report "FAIL: " & test_name & " - DATA_COUNT is incorrect."
                severity failure;

            if expected_count = DEPTH then
                assert full = '1'
                    report "FAIL: " & test_name & " - FULL should be asserted."
                    severity failure;
            else
                assert full = '0'
                    report "FAIL: " & test_name & " - FULL should be deasserted."
                    severity failure;
            end if;

            if expected_count = 0 then
                assert empty = '1'
                    report "FAIL: " & test_name & " - EMPTY should be asserted."
                    severity failure;
            else
                assert empty = '0'
                    report "FAIL: " & test_name & " - EMPTY should be deasserted."
                    severity failure;
            end if;

            if expected_count >= ALMOST_FULL_THRESHOLD then
                assert almost_full = '1'
                    report "FAIL: " & test_name & " - ALMOST_FULL should be asserted."
                    severity failure;
            else
                assert almost_full = '0'
                    report "FAIL: " & test_name & " - ALMOST_FULL should be deasserted."
                    severity failure;
            end if;

            if expected_count <= ALMOST_EMPTY_THRESHOLD then
                assert almost_empty = '1'
                    report "FAIL: " & test_name & " - ALMOST_EMPTY should be asserted."
                    severity failure;
            else
                assert almost_empty = '0'
                    report "FAIL: " & test_name & " - ALMOST_EMPTY should be deasserted."
                    severity failure;
            end if;
        end procedure;

        procedure write_word(
            constant value         : in std_logic_vector(WIDTH - 1 downto 0);
            constant expected_count : in natural;
            constant test_name     : in string
        ) is
        begin
            din   <= value;
            wr_en <= '1';
            rd_en <= '0';
            cycle;
            wr_en <= '0';
            check_state(expected_count, test_name);
        end procedure;

        procedure read_word(
            constant expected_value : in std_logic_vector(WIDTH - 1 downto 0);
            constant expected_count : in natural;
            constant test_name      : in string
        ) is
        begin
            rd_en <= '1';
            wr_en <= '0';
            cycle;
            rd_en <= '0';
            check_state(expected_count, test_name);

            -- The read data and VALID appear after the configured latency.
            for latency_clock in 2 to G_READ_LATENCY loop
                cycle;
            end loop;

            assert valid = '1'
                report "FAIL: " & test_name & " - VALID was not asserted for the read."
                severity failure;
            assert dout = expected_value
                report "FAIL: " & test_name & " - DOUT did not match the expected word."
                severity failure;

            cycle;
            assert valid = '0'
                report "FAIL: " & test_name & " - VALID did not return low."
                severity failure;
        end procedure;
    begin
        -- Load the 32 expected words generated by the Python script.
        file_open(file_status, input_file, G_INPUT_FILE, read_mode);
        assert file_status = open_ok
            report "FAIL: Could not open input data file: " & G_INPUT_FILE
            severity failure;
        if file_status /= open_ok then
            stop;
            wait;
        end if;

        for i in 0 to DEPTH - 1 loop
            assert not endfile(input_file)
                report "FAIL: input_data.txt has fewer than DEPTH words."
                severity failure;
            readline(input_file, input_line);
            hread(input_line, parsed_word);
            file_words(i) := parsed_word;
        end loop;

        assert endfile(input_file)
            report "FAIL: input_data.txt must contain exactly DEPTH words."
            severity failure;
        file_close(input_file);

        report "TEST 1: reset clears pointers, count, VALID, and output." severity note;
        srst  <= '1';
        wr_en <= '1';
        rd_en <= '1';
        din   <= x"DEAD";
        cycle;
        check_state(0, "reset");
        assert valid = '0'
            report "FAIL: reset - VALID must be low."
            severity failure;
        assert dout = x"0000"
            report "FAIL: reset - DOUT must return to 0."
            severity failure;

        srst  <= '0';
        wr_en <= '0';
        rd_en <= '0';
        cycle;
        check_state(0, "after reset");

        write_word(x"CAFE", 1, "reset output setup");
        read_word(x"CAFE", 0, "reset output setup read");

        srst <= '1';
        cycle;
        check_state(0, "reset after data was read");
        assert valid = '0' and dout = x"0000"
            report "FAIL: reset after a read must clear VALID and DOUT."
            severity failure;
        srst <= '0';
        cycle;
        check_state(0, "reset released");
        report "PASS: reset." severity note;

        report "TEST 2: disabled enables and an empty read do not change state." severity note;
        din <= x"FFFF";
        cycle;
        check_state(0, "idle with enables low");

        wr_en <= '0';
        cycle;
        check_state(0, "write disabled");

        rd_en <= '1';
        cycle;
        rd_en <= '0';
        check_state(0, "read while empty");
        assert valid = '0'
            report "FAIL: underflow request must not assert VALID."
            severity failure;
        report "PASS: enable gating and ignored empty read." severity note;

        report "TEST 3: fill/read all ones, then fill/read all zeros." severity note;
        for i in 0 to DEPTH - 1 loop
            write_word(x"FFFF", i + 1, "all-ones write");
        end loop;
        check_state(DEPTH, "all-ones FIFO full");

        for i in 0 to DEPTH - 1 loop
            read_word(x"FFFF", DEPTH - i - 1, "all-ones read");
        end loop;

        for i in 0 to DEPTH - 1 loop
            write_word(x"0000", i + 1, "all-zeros write");
        end loop;
        check_state(DEPTH, "all-zeros FIFO full");

        for i in 0 to DEPTH - 1 loop
            read_word(x"0000", DEPTH - i - 1, "all-zeros read");
        end loop;
        check_state(0, "after all-zero test");
        report "PASS: all-ones and all-zeros data patterns." severity note;

        report "TEST 4: alternating AAAA and 5555 patterns preserve order." severity note;
        write_word(x"AAAA", 1, "alternating write");
        write_word(x"5555", 2, "alternating write");
        write_word(x"AAAA", 3, "alternating write");
        write_word(x"5555", 4, "alternating write");

        read_word(x"AAAA", 3, "alternating read 1");
        read_word(x"5555", 2, "alternating read 2");
        read_word(x"AAAA", 1, "alternating read 3");
        read_word(x"5555", 0, "alternating read 4");
        report "PASS: alternating bit patterns." severity note;

        report "TEST 5: generated data, FIFO addresses, thresholds, and overflow." severity note;
        for i in 0 to DEPTH - 1 loop
            write_word(file_words(i), i + 1, "file data write");
            if (i + 1) = ALMOST_FULL_THRESHOLD then
                check_state(ALMOST_FULL_THRESHOLD, "almost-full threshold");
            end if;
        end loop;
        check_state(DEPTH, "all addresses written / full");

        -- This extra write must be ignored because the FIFO is full.
        din   <= x"DEAD";
        wr_en <= '1';
        cycle;
        wr_en <= '0';
        check_state(DEPTH, "overflow write ignored");

        for i in 0 to DEPTH - 1 loop
            read_word(file_words(i), DEPTH - i - 1, "file data readback");
            if (DEPTH - i - 1) = ALMOST_EMPTY_THRESHOLD then
                check_state(ALMOST_EMPTY_THRESHOLD, "almost-empty threshold");
            end if;
        end loop;
        check_state(0, "FIFO empty after readback");
        report "PASS: generated data and status thresholds." severity note;

        report "TEST 6: simultaneous read/write while partially full." severity note;
        write_word(x"C001", 1, "simultaneous middle setup");
        write_word(x"C002", 2, "simultaneous middle setup");
        write_word(x"C003", 3, "simultaneous middle setup");

        din   <= x"C004";
        wr_en <= '1';
        rd_en <= '1';
        cycle;
        wr_en <= '0';
        rd_en <= '0';
        check_state(3, "simultaneous read/write with data present");

        for latency_clock in 2 to G_READ_LATENCY loop
            cycle;
        end loop;
        assert valid = '1' and dout = x"C001"
            report "FAIL: simultaneous middle operation returned wrong oldest word."
            severity failure;

        cycle;
        assert valid = '0'
            report "FAIL: simultaneous middle operation VALID pulse did not end."
            severity failure;

        read_word(x"C002", 2, "simultaneous middle readback 2");
        read_word(x"C003", 1, "simultaneous middle readback 3");
        read_word(x"C004", 0, "simultaneous middle readback 4");
        report "PASS: simultaneous read/write at intermediate occupancy." severity note;

        report "TEST 7: at full, simultaneous read/write accepts only the read." severity note;
        for i in 0 to DEPTH - 1 loop
            write_word(file_words(i), i + 1, "full simultaneous setup");
        end loop;

        din   <= x"BEEF";
        wr_en <= '1';
        rd_en <= '1';
        cycle;
        wr_en <= '0';
        rd_en <= '0';
        check_state(DEPTH - 1, "full simultaneous request");

        for latency_clock in 2 to G_READ_LATENCY loop
            cycle;
        end loop;
        assert valid = '1' and dout = file_words(0)
            report "FAIL: full simultaneous request did not return oldest word."
            severity failure;

        cycle;
        assert valid = '0'
            report "FAIL: full simultaneous VALID pulse did not end."
            severity failure;

        for i in 1 to DEPTH - 1 loop
            read_word(file_words(i), DEPTH - i - 1, "full simultaneous remaining data");
        end loop;
        check_state(0, "after full simultaneous test");
        report "PASS: full simultaneous rule." severity note;

        report "TEST 8: at empty, simultaneous read/write accepts only the write." severity note;
        din   <= x"E111";
        wr_en <= '1';
        rd_en <= '1';
        cycle;
        wr_en <= '0';
        rd_en <= '0';
        check_state(1, "empty simultaneous request");
        assert valid = '0'
            report "FAIL: empty simultaneous request must not accept a read."
            severity failure;
        read_word(x"E111", 0, "empty simultaneous inserted word");
        report "PASS: empty simultaneous rule." severity note;

        report "TEST 9: consecutive reads keep data and VALID aligned." severity note;
        for i in 0 to 4 loop
            write_word(file_words(i), i + 1, "burst-read setup");
        end loop;

        for i in 0 to 4 + G_READ_LATENCY - 1 loop
            if i < 5 then
                rd_en <= '1';
            else
                rd_en <= '0';
            end if;
            cycle;

            if i < 5 then
                check_state(5 - i - 1, "burst read count");
            else
                check_state(0, "burst read drain");
            end if;

            if (i >= G_READ_LATENCY - 1) and
               (i < 5 + G_READ_LATENCY - 1) then
                assert valid = '1'
                    report "FAIL: burst read - VALID missing from pipeline."
                    severity failure;
                assert dout = file_words(i - (G_READ_LATENCY - 1))
                    report "FAIL: burst read - DOUT/VALID alignment is incorrect."
                    severity failure;
            else
                assert valid = '0'
                    report "FAIL: burst read - VALID asserted in an empty pipeline slot."
                    severity failure;
            end if;
        end loop;

        rd_en <= '0';
        cycle;
        check_state(0, "after burst read");
        assert valid = '0'
            report "FAIL: burst read - VALID did not clear after the final word."
            severity failure;
        report "PASS: consecutive reads and pipeline alignment." severity note;

        report "ALL TEST CASES PASSED." severity note;
        stop;
        wait;
    end process;
end architecture simulation;